// scripts/build-scheduler-bundle.js
// ---------------------------------------------------------------------------
// Bundles the app's pure scheduling code (src/utils/scheduler-entry.ts → auto-assign →
// projection / queue / resolver / race) into ONE dependency-free ES module for the
// auto-assign-run Edge Function, so the server runs the exact same scheduler as the app.
//   npm run build:scheduler            → (re)writes supabase/functions/_shared/scheduler.bundle.js
//   node scripts/build-scheduler-bundle.js --check → exit 1 if the committed bundle is stale
// supabase/tests/auto_assign_core.test.ts runs the same check.
// ---------------------------------------------------------------------------
/* global __dirname */
const fs = require("fs");
const path = require("path");
const esbuild = require("esbuild");

const root = path.join(__dirname, "..");
const outFile = path.join(root, "supabase", "functions", "_shared", "scheduler.bundle.js");
const BANNER =
  "// GENERATED by scripts/build-scheduler-bundle.js from src/utils/scheduler-entry.ts — DO NOT EDIT.\n" +
  "// The app's own scheduling code (projection, queue pins, Play Next, planner), bundled for Deno.\n" +
  "// Rebuild with `npm run build:scheduler`; supabase/tests/scheduler_bundle.test.ts fails if stale.\n";

function buildBundle() {
  const result = esbuild.buildSync({
    absWorkingDir: root,
    entryPoints: ["src/utils/scheduler-entry.ts"],
    bundle: true,
    format: "esm",
    platform: "neutral",
    target: "es2020",
    write: false,
    legalComments: "none",
    logLevel: "silent",
  });
  return BANNER + result.outputFiles[0].text;
}

module.exports = { buildBundle, outFile };

if (require.main === module) {
  const fresh = buildBundle();
  if (process.argv.includes("--check")) {
    const current = fs.existsSync(outFile) ? fs.readFileSync(outFile, "utf8").replace(/\r\n/g, "\n") : "";
    if (current !== fresh) {
      console.error("[build:scheduler] scheduler.bundle.js is STALE — run `npm run build:scheduler`.");
      process.exit(1);
    }
    console.log("[build:scheduler] bundle is up to date.");
  } else {
    fs.writeFileSync(outFile, fresh);
    console.log(`[build:scheduler] wrote ${path.relative(root, outFile)} (${fresh.length} bytes)`);
  }
}
